#define SKIP_SPACES_COMMENTS(parser, chunk, p)                                    \
	do {                                                                          \
		while ((p) < (chunk)->end) {                                              \
			if (!ucl_test_character(*(p), UCL_CHARACTER_WHITESPACE_UNSAFE)) {     \
				if ((chunk)->remain >= 2 && ucl_lex_is_comment((p)[0], (p)[1])) { \
					if (!ucl_skip_comments(parser)) {                             \
						return false;                                             \
					}                                                             \
					p = (chunk)->pos;                                             \
				}                                                                 \
				break;                                                            \
			}                                                                     \
			ucl_chunk_skipc(chunk, p);                                            \
		}                                                                         \
	} while (0)
